SELECT DATE(date_order_placed) AS transaction_date
FROM Orders
WHERE date_order_placed >= '2018-01-01' AND date_order_placed < '2019-01-01';

SELECT DATE(invoice_date) AS invoice_date
FROM Invoices
WHERE strftime('%Y', invoice_date) = '2018';

